// Aceita o lead do jeito que a origem mandar e devolve no formato do QS.
// Só o telefone é tratado a sério: o QS deduplica por ele, então "62 99999-0001"
// e "5562999990001" precisam virar a MESMA coisa, senão o mesmo cliente entra
// duas vezes.
const entrada = $input.first().json;
const b = entrada.body ?? entrada;   // o Webhook do n8n embrulha o corpo em .body

const txt = (...chaves) => {
  for (const k of chaves) {
    const v = b[k];
    if (v != null && String(v).trim() !== '') return String(v).trim();
  }
  return null;
};

function telefone(v) {
  let d = String(v ?? '').replace(/\D/g, '');
  if (!d) return null;
  d = d.replace(/^0+/, '');           // tira 0 de operadora
  if (!d.startsWith('55')) d = '55' + d;
  // 55 + DDD(2) + número(8 ou 9)
  return (d.length === 12 || d.length === 13) ? d : null;
}

return [{ json: {
  full_name:    txt('full_name', 'nome', 'name', 'Nome', 'NOME', 'cliente'),
  phone:        telefone(txt('phone', 'telefone', 'whatsapp', 'celular', 'Telefone', 'WhatsApp', 'Celular')),
  email:        txt('email', 'e-mail', 'Email', 'E-mail', 'EMAIL'),
  // Fonte aparece no card do lead. Deixe reconhecível pra saber de onde veio.
  segment:      txt('segment', 'fonte', 'origem', 'Fonte', 'Origem') ?? 'Resgate',
  source:       txt('source') ?? 'resgate',
  city:         txt('city', 'cidade', 'Cidade'),
  state:        txt('state', 'estado', 'uf', 'UF'),
  company_name: txt('company_name', 'empresa', 'Empresa'),
  bitrix_id:    txt('bitrix_id', 'id_bitrix', 'ID'),
} }];

// Traduz a resposta do QS pra algo legível no histórico do n8n.
const r = $input.first().json;
const status = r.statusCode ?? 0;
const corpo = r.body ?? {};

let resultado, detalhe;
if (status === 200 && corpo.success) {
  resultado = corpo.deduped ? 'ja_existia' : 'criado';
  detalhe = corpo.deduped
    ? 'Esse lead JÁ estava no QS. Nada foi alterado — ele continua na cadência em que estava.'
    : `Lead criado com ${corpo.tasks_created} atividades na cadência de resgate.`;
} else if (status === 401) {
  resultado = 'erro';
  detalhe = 'Segredo recusado. Confira o header x-lead-secret no nó "Enviar para o QS".';
} else if (status === 400) {
  resultado = 'erro';
  detalhe = corpo.error || 'Faltou telefone, e-mail ou nome.';
} else {
  resultado = 'erro';
  detalhe = corpo.error || `Falha inesperada (HTTP ${status}).`;
}

return [{ json: {
  resultado,
  detalhe,
  lead_id: corpo.lead_id ?? null,
  lista: corpo.lista ?? null,
  cadence_id: corpo.cadence_id ?? null,
} }];
